package local.civic.home;
import android.content.*;import android.content.pm.*;import android.content.res.*;import android.graphics.drawable.Drawable;import android.util.Xml;import org.xmlpull.v1.XmlPullParser;import java.io.*;import java.util.*;

final class IconPacks {
 static final String KEY="icon_pack";static final String[] ACTIONS={"com.novalauncher.THEME","org.adw.launcher.THEMES","com.anddoes.launcher.THEME","com.gau.go.launcherex.theme","com.teslacoilsw.launcher.THEME"};
 static ArrayList<ResolveInfo> installed(Context c){PackageManager pm=c.getPackageManager();LinkedHashMap<String,ResolveInfo> found=new LinkedHashMap<>();for(String action:ACTIONS)for(ResolveInfo r:pm.queryIntentActivities(new Intent(action),0))if(r.activityInfo!=null)found.put(r.activityInfo.packageName,r);ArrayList<ResolveInfo> out=new ArrayList<>(found.values());Collections.sort(out,new ResolveInfo.DisplayNameComparator(pm));return out;}
 static String name(Context c){String pkg=c.getSharedPreferences("home",0).getString(KEY,"");if(pkg.isEmpty())return "Simple Icons";try{return c.getPackageManager().getApplicationLabel(c.getPackageManager().getApplicationInfo(pkg,0)).toString();}catch(Exception e){return "Pack unavailable";}}
 static final class Pack {final Resources resources;final String pkg;final HashMap<String,Integer> drawableIds=new HashMap<>();final HashMap<String,String> components=new HashMap<>(),packages=new HashMap<>();Pack(Resources r,String p){resources=r;pkg=p;}String lookup(Context c,String app,String cls){if(cls==null)try{Intent i=c.getPackageManager().getLaunchIntentForPackage(app);if(i!=null&&i.getComponent()!=null)cls=i.getComponent().getClassName();}catch(Exception ignored){}String exact=cls==null?null:components.get(new ComponentName(app,cls).flattenToString());return exact!=null?exact:packages.get(app);}synchronized int drawableId(String name){Integer cached=drawableIds.get(name);if(cached!=null)return cached;int id=resources.getIdentifier(name,"drawable",pkg);if(id==0)id=resources.getIdentifier(name,"mipmap",pkg);drawableIds.put(name,id);return id;}Drawable drawable(String name){try{int id=drawableId(name);return id==0?null:resources.getDrawable(id,null);}catch(RuntimeException e){return null;}}}
 static Pack load(Context c){String pkg=c.getSharedPreferences("home",0).getString(KEY,"");if(pkg.isEmpty())return null;try{Resources r=c.getPackageManager().getResourcesForApplication(pkg);Pack pack=new Pack(r,pkg);XmlPullParser parser;InputStream stream=null;int id=r.getIdentifier("appfilter","xml",pkg);if(id!=0)parser=r.getXml(id);else{stream=r.getAssets().open("appfilter.xml");parser=Xml.newPullParser();parser.setInput(stream,"UTF-8");}try{for(int event=parser.getEventType();event!=XmlPullParser.END_DOCUMENT;event=parser.next()){if(event!=XmlPullParser.START_TAG||!"item".equals(parser.getName()))continue;String component=parser.getAttributeValue(null,"component"),drawable=parser.getAttributeValue(null,"drawable");if(component==null||drawable==null||!component.startsWith("ComponentInfo{")||!component.endsWith("}"))continue;ComponentName name=ComponentName.unflattenFromString(component.substring(14,component.length()-1));if(name==null)continue;pack.components.put(name.flattenToString(),drawable);if(!pack.packages.containsKey(name.getPackageName()))pack.packages.put(name.getPackageName(),drawable);}}finally{if(stream!=null)stream.close();if(parser instanceof android.content.res.XmlResourceParser)((android.content.res.XmlResourceParser)parser).close();}return pack;}catch(Exception e){return null;}}
}
